const rows = $input.all().map(item => item.json);

// Получаем выбранный период из узла Edit Fields
const period = $('Edit Fields').first().json.period;

let filteredRows = rows;

if (period !== 'all') {
  const days = Number(period);
  const now = Date.now();
  const cutoff = now - days * 24 * 60 * 60 * 1000;

  filteredRows = rows.filter(row => {
    const date = new Date(row.created_at).getTime();
    return !isNaN(date) && date >= cutoff && date <= now;
  });
}

const countBy = (field) => {
  return filteredRows.reduce((result, row) => {
    const value = row[field] || 'unknown';
    result[value] = (result[value] || 0) + 1;
    return result;
  }, {});
};

const humanRequired = filteredRows.filter(row =>
  row.requires_human === true || row.requires_human === 'true'
).length;

return [{
  json: {
    period: period,
    total_requests: filteredRows.length,
    by_category: countBy('category'),
    by_priority: countBy('priority'),
    requires_human: humanRequired,
    no_human_required: filteredRows.length - humanRequired
  }
}];

